/* Three reading stories, A1 / A2 / B1, five lines each with Arabic translation. */
STORIES.zh=[
{level:"A1",title:"يومي",s:[["我叫阿里。","اسمي علي."],["我二十岁。","عمري عشرون سنة."],["我住在开罗。","أعيش في القاهرة."],["我喜欢喝咖啡。","أحب شرب القهوة."],["我每天学中文。","أتعلم الصينية كل يوم."]]},
{level:"A2",title:"رحلة إلى بكين",s:[["去年我去了北京。","سافرت إلى بكين العام الماضي."],["我参观了长城。","زرت سور الصين العظيم."],["我和朋友吃了北京烤鸭。","أكلت بطة بكين مع أصدقائي."],["天气非常好。","كان الطقس جميلاً جداً."],["我想明年再去一次。","أريد الذهاب مرة أخرى العام القادم."]]},
{level:"B1",title:"قرار مهم",s:[["小时候我想当医生。","عندما كنت صغيراً أردت أن أصبح طبيباً."],["但是后来我发现了我对语言的兴趣。","لكنني اكتشفت لاحقاً شغفي باللغات."],["我决定在大学学习翻译。","قررت دراسة الترجمة في الجامعة."],["虽然这条路很难，但是我没有放弃。","رغم أن الطريق صعب، لم أستسلم."],["今天我会说四种语言，而且还在继续学习。","اليوم أتحدث أربع لغات وما زلت أتعلم."]]}];

